import { describe, test, expect, beforeEach, afterEach } from "bun:test"
import { mkdtempSync, writeFileSync, rmSync } from "fs"
import { join } from "path"
import { tmpdir } from "os"

import { loadAgentDefinitions, parseMarkdownAgentFile } from "./agent-definitions-loader"

describe("agent-definitions-loader", () => {
  let tempDir: string

  beforeEach(() => {
    tempDir = mkdtempSync(join(tmpdir(), "agent-definitions-test-"))
  })

  afterEach(() => {
    rmSync(tempDir, { recursive: true, force: true })
  })

  describe("#parseMarkdownAgentFile", () => {
    test("parses valid markdown agent file", () => {
      const filePath = join(tempDir, "test-agent.md")
      const content = `---
name: test-agent
description: A test agent
model: claude-opus-4
mode: subagent
tools: bash,read
---

You are a test agent.`

      writeFileSync(filePath, content, "utf-8")

      const result = parseMarkdownAgentFile(filePath, "definition-file")

      expect(result).not.toBeNull()
      expect(result?.name).toBe("test-agent")
      expect(result?.config.description).toBe("(definition-file) A test agent")
      expect(result?.config.mode).toBe("subagent")
      expect(result?.config.prompt).toBe("You are a test agent.")
      expect(result?.config.tools).toEqual({ bash: true, read: true })
    })

    test("uses filename as agent name if name not specified in frontmatter", () => {
      const filePath = join(tempDir, "custom-name.md")
      const content = `---
description: No name specified
---

Prompt content.`

      writeFileSync(filePath, content, "utf-8")

      const result = parseMarkdownAgentFile(filePath, "definition-file")

      expect(result).not.toBeNull()
      expect(result?.name).toBe("custom-name")
    })

    test("returns null for missing file", () => {
      const filePath = join(tempDir, "missing.md")
      const result = parseMarkdownAgentFile(filePath, "definition-file")

      expect(result).toBeNull()
    })

    test("handles malformed frontmatter gracefully with defaults", () => {
      const filePath = join(tempDir, "malformed.md")
      const content = `---
invalid: yaml: content: here
---

Prompt.`

      writeFileSync(filePath, content, "utf-8")

      const result = parseMarkdownAgentFile(filePath, "definition-file")

      expect(result).not.toBeNull()
      expect(result?.name).toBe("malformed")
      expect(result?.config.mode).toBe("subagent")
      expect(result?.config.prompt).toBe("Prompt.")
    })

    test("strips .MD extension case-insensitively for agent name", () => {
      const filePath = join(tempDir, "UpperCase.MD")
      const content = `---
description: Mixed case extension
---

Prompt content.`

      writeFileSync(filePath, content, "utf-8")

      const result = parseMarkdownAgentFile(filePath, "definition-file")

      expect(result).not.toBeNull()
      expect(result?.name).toBe("UpperCase")
    })

    test("defaults mode to subagent when not specified", () => {
      const filePath = join(tempDir, "no-mode.md")
      const content = `---
name: no-mode-agent
---

Prompt.`

      writeFileSync(filePath, content, "utf-8")

      const result = parseMarkdownAgentFile(filePath, "definition-file")

      expect(result).not.toBeNull()
      expect(result?.config.mode).toBe("subagent")
    })

    test("maps Claude aliases to configured anthropic provider", () => {
      const filePath = join(tempDir, "custom-provider.md")
      const content = `---
name: custom-provider-agent
model: opus
---

Prompt.`

      writeFileSync(filePath, content, "utf-8")

      const result = parseMarkdownAgentFile(filePath, "definition-file", "kiro")

      expect(result?.config.model).toBe("kiro/claude-opus-4-7")
    })
  })

  describe("#loadAgentDefinitions", () => {
    test("loads mixed format files (markdown and JSON)", () => {
      const mdPath = join(tempDir, "agent1.md")
      const jsonPath = join(tempDir, "agent2.json")

      writeFileSync(
        mdPath,
        `---
name: md-agent
---

Markdown agent prompt.`,
        "utf-8"
      )

      writeFileSync(
        jsonPath,
        JSON.stringify({
          name: "json-agent",
          prompt: "JSON agent prompt.",
        }),
        "utf-8"
      )

      const result = loadAgentDefinitions([mdPath, jsonPath], "definition-file")

      expect(Object.keys(result)).toHaveLength(2)
      expect(result["md-agent"]).toBeDefined()
      expect(result["json-agent"]).toBeDefined()
      expect(result["md-agent"].prompt).toBe("Markdown agent prompt.")
      expect(result["json-agent"].prompt).toBe("JSON agent prompt.")
    })

    test("silently skips missing files with warning log", () => {
      const validPath = join(tempDir, "valid.md")
      const missingPath = join(tempDir, "missing.md")

      writeFileSync(
        validPath,
        `---
name: valid-agent
---

Valid prompt.`,
        "utf-8"
      )

      const result = loadAgentDefinitions([validPath, missingPath], "definition-file")

      expect(Object.keys(result)).toHaveLength(1)
      expect(result["valid-agent"]).toBeDefined()
    })

    test("silently skips malformed files with warning log", () => {
      const validPath = join(tempDir, "valid.jsonc")
      const malformedPath = join(tempDir, "malformed.json")

      writeFileSync(
        validPath,
        JSON.stringify({
          name: "valid-agent",
          prompt: "Valid prompt.",
        }),
        "utf-8"
      )

      writeFileSync(malformedPath, "{ invalid json", "utf-8")

      const result = loadAgentDefinitions([validPath, malformedPath], "definition-file")

      expect(Object.keys(result)).toHaveLength(1)
      expect(result["valid-agent"]).toBeDefined()
    })

    test("last-write-wins for duplicate agent names", () => {
      const path1 = join(tempDir, "agent-v1.md")
      const path2 = join(tempDir, "agent-v2.md")

      writeFileSync(
        path1,
        `---
name: duplicate-agent
description: First version
---

First prompt.`,
        "utf-8"
      )

      writeFileSync(
        path2,
        `---
name: duplicate-agent
description: Second version
---

Second prompt.`,
        "utf-8"
      )

      const result = loadAgentDefinitions([path1, path2], "definition-file")

      expect(Object.keys(result)).toHaveLength(1)
      expect(result["duplicate-agent"].description).toBe("(definition-file) Second version")
      expect(result["duplicate-agent"].prompt).toBe("Second prompt.")
    })

    test("returns empty object for empty paths array", () => {
      const result = loadAgentDefinitions([], "definition-file")

      expect(result).toEqual({})
    })

    test("handles absolute paths correctly", () => {
      const absolutePath = join(tempDir, "absolute.md")

      writeFileSync(
        absolutePath,
        `---
name: absolute-agent
---

Absolute path prompt.`,
        "utf-8"
      )

      const result = loadAgentDefinitions([absolutePath], "definition-file")

      expect(Object.keys(result)).toHaveLength(1)
      expect(result["absolute-agent"]).toBeDefined()
    })

    test("skips unsupported file extensions with warning", () => {
      const validPath = join(tempDir, "valid.md")
      const unsupportedPath = join(tempDir, "unsupported.txt")

      writeFileSync(
        validPath,
        `---
name: valid-agent
---

Valid prompt.`,
        "utf-8"
      )

      writeFileSync(unsupportedPath, "Some text file content.", "utf-8")

      const result = loadAgentDefinitions([validPath, unsupportedPath], "definition-file")

      expect(Object.keys(result)).toHaveLength(1)
      expect(result["valid-agent"]).toBeDefined()
    })

    test("supports JSONC format with comments", () => {
      const jsoncPath = join(tempDir, "agent.jsonc")

      writeFileSync(
        jsoncPath,
        `{
  // This is a comment
  "name": "jsonc-agent",
  "description": "JSONC agent", // inline comment
  "prompt": "JSONC prompt."
}`,
        "utf-8"
      )

      const result = loadAgentDefinitions([jsoncPath], "definition-file")

      expect(Object.keys(result)).toHaveLength(1)
      expect(result["jsonc-agent"]).toBeDefined()
      expect(result["jsonc-agent"].prompt).toBe("JSONC prompt.")
    })

    test("passes anthropic provider override to markdown definitions", () => {
      const mdPath = join(tempDir, "provider-agent.md")

      writeFileSync(
        mdPath,
        `---
name: provider-agent
model: sonnet
---

Provider prompt.`,
        "utf-8"
      )

      const result = loadAgentDefinitions([mdPath], "definition-file", "kiro")

      expect(result["provider-agent"].model).toBe("kiro/claude-sonnet-4-6")
    })
  })
})

import { existsSync, readFileSync } from "fs"
import { basename, extname } from "path"
import { parseFrontmatter } from "../../shared/frontmatter"
import { log } from "../../shared/logger"
import { parseToolsConfig } from "../../shared/parse-tools-config"
import { parseJsonAgentFile } from "./json-agent-loader"
import { mapClaudeModelToOpenCode } from "./claude-model-mapper"
import type { AgentScope, AgentFrontmatter, ClaudeCodeAgentConfig, LoadedAgent } from "./types"

export function parseMarkdownAgentFile(
  filePath: string,
  scope: AgentScope,
  anthropicProvider?: string,
): LoadedAgent | null {
  try {
    if (!existsSync(filePath)) {
      return null
    }

    const content = readFileSync(filePath, "utf-8")
    const { data, body } = parseFrontmatter<AgentFrontmatter>(content)

    const fileName = basename(filePath)
    const agentName = fileName.replace(/\.md$/i, "")
    const name = data.name || agentName
    const originalDescription = data.description || ""

    const formattedDescription = `(${scope}) ${originalDescription}`

    const mappedModelOverride = mapClaudeModelToOpenCode(data.model, anthropicProvider)
    const modelString = mappedModelOverride
      ? `${mappedModelOverride.providerID}/${mappedModelOverride.modelID}`
      : undefined

    const config: ClaudeCodeAgentConfig = {
      description: formattedDescription,
      mode: data.mode || "subagent",
      prompt: body.trim(),
      ...(modelString ? { model: modelString } : {}),
    }

    const toolsConfig = parseToolsConfig(data.tools)
    if (toolsConfig) {
      config.tools = toolsConfig
    }

    return {
      name,
      path: filePath,
      config,
      scope,
    }
  } catch (error) {
    if (error instanceof Error) return null
    return null
  }
}

export function loadAgentDefinitions(
  paths: string[],
  scope: AgentScope,
  anthropicProvider?: string,
): Record<string, ClaudeCodeAgentConfig> {
  const result: Record<string, ClaudeCodeAgentConfig> = Object.create(null)

  for (const filePath of paths) {
    if (!existsSync(filePath)) {
      log(`[agent-definitions-loader] File not found, skipping: ${filePath}`)
      continue
    }

    const ext = extname(filePath).toLowerCase()
    let agent: LoadedAgent | null = null

    if (ext === ".md") {
      agent = parseMarkdownAgentFile(filePath, scope, anthropicProvider)
    } else if (ext === ".json" || ext === ".jsonc") {
      agent = parseJsonAgentFile(filePath, scope)
    } else {
      log(`[agent-definitions-loader] Unsupported file extension: ${ext} for ${filePath}`)
      continue
    }

    if (!agent) {
      log(`[agent-definitions-loader] Failed to parse agent file: ${filePath}`)
      continue
    }

    result[agent.name] = agent.config
  }

  return result
}

/// <reference types="bun-types" />

import { describe, it, expect } from "bun:test"
import { mapClaudeModelToOpenCode } from "./claude-model-mapper"

describe("mapClaudeModelToOpenCode", () => {
  describe("#given undefined or empty input", () => {
    it("#when called with undefined #then returns undefined", () => {
      expect(mapClaudeModelToOpenCode(undefined)).toBeUndefined()
    })

    it("#when called with empty string #then returns undefined", () => {
      expect(mapClaudeModelToOpenCode("")).toBeUndefined()
    })

    it("#when called with whitespace-only string #then returns undefined", () => {
      expect(mapClaudeModelToOpenCode("   ")).toBeUndefined()
    })
  })

  describe("#given Claude Code alias", () => {
    it("#when called with sonnet #then maps to anthropic claude-sonnet-4-6 object", () => {
      expect(mapClaudeModelToOpenCode("sonnet")).toEqual({ providerID: "anthropic", modelID: "claude-sonnet-4-6" })
    })

    it("#when called with opus #then maps to anthropic claude-opus-4-7 object", () => {
      expect(mapClaudeModelToOpenCode("opus")).toEqual({ providerID: "anthropic", modelID: "claude-opus-4-7" })
    })

    it("#when called with haiku #then maps to anthropic claude-haiku-4-5 object", () => {
      expect(mapClaudeModelToOpenCode("haiku")).toEqual({ providerID: "anthropic", modelID: "claude-haiku-4-5" })
    })

    it("#when called with Sonnet (capitalized) #then maps case-insensitively to object", () => {
      expect(mapClaudeModelToOpenCode("Sonnet")).toEqual({ providerID: "anthropic", modelID: "claude-sonnet-4-6" })
    })
  })

  describe("#given inherit", () => {
    it("#when called with inherit #then returns undefined", () => {
      expect(mapClaudeModelToOpenCode("inherit")).toBeUndefined()
    })
  })

  describe("#given bare Claude model name", () => {
    it("#when called with claude-sonnet-4-5-20250514 #then adds anthropic object format", () => {
      expect(mapClaudeModelToOpenCode("claude-sonnet-4-5-20250514")).toEqual({ providerID: "anthropic", modelID: "claude-sonnet-4-5-20250514" })
    })

    it("#when called with claude-opus-4-7 #then adds anthropic object format", () => {
      expect(mapClaudeModelToOpenCode("claude-opus-4-7")).toEqual({ providerID: "anthropic", modelID: "claude-opus-4-7" })
    })

    it("#when called with claude-haiku-4-5-20251001 #then adds anthropic object format", () => {
      expect(mapClaudeModelToOpenCode("claude-haiku-4-5-20251001")).toEqual({ providerID: "anthropic", modelID: "claude-haiku-4-5-20251001" })
    })

    it("#when called with claude-3-5-sonnet-20241022 #then adds anthropic object format", () => {
      expect(mapClaudeModelToOpenCode("claude-3-5-sonnet-20241022")).toEqual({ providerID: "anthropic", modelID: "claude-3-5-sonnet-20241022" })
    })
  })

  describe("#given model with dot version numbers", () => {
    it("#when called with claude-3.5-sonnet #then normalizes dots and returns object format", () => {
      expect(mapClaudeModelToOpenCode("claude-3.5-sonnet")).toEqual({ providerID: "anthropic", modelID: "claude-3-5-sonnet" })
    })

    it("#when called with claude-3.5-sonnet-20241022 #then normalizes dots and returns object format", () => {
      expect(mapClaudeModelToOpenCode("claude-3.5-sonnet-20241022")).toEqual({ providerID: "anthropic", modelID: "claude-3-5-sonnet-20241022" })
    })
  })

  describe("#given model already in provider/model format", () => {
    it("#when called with anthropic/claude-sonnet-4-6 #then splits into object format", () => {
      expect(mapClaudeModelToOpenCode("anthropic/claude-sonnet-4-6")).toEqual({ providerID: "anthropic", modelID: "claude-sonnet-4-6" })
    })

    it("#when called with anthropic/claude-3.5-sonnet #then normalizes dots before splitting into object format", () => {
      expect(mapClaudeModelToOpenCode("anthropic/claude-3.5-sonnet")).toEqual({ providerID: "anthropic", modelID: "claude-3-5-sonnet" })
    })

    it("#when called with openai/gpt-5.5 #then splits into object format", () => {
      expect(mapClaudeModelToOpenCode("openai/gpt-5.5")).toEqual({ providerID: "openai", modelID: "gpt-5.5" })
    })
  })

  describe("#given non-Claude bare model", () => {
    it("#when called with gpt-5.5 #then returns undefined", () => {
      expect(mapClaudeModelToOpenCode("gpt-5.5")).toBeUndefined()
    })

    it("#when called with gemini-3-flash #then returns undefined", () => {
      expect(mapClaudeModelToOpenCode("gemini-3-flash")).toBeUndefined()
    })
  })

  describe("#given prototype property name", () => {
    it("#when called with constructor #then returns undefined", () => {
      expect(mapClaudeModelToOpenCode("constructor")).toBeUndefined()
    })

    it("#when called with toString #then returns undefined", () => {
      expect(mapClaudeModelToOpenCode("toString")).toBeUndefined()
    })
  })

  describe("#given model with leading/trailing whitespace", () => {
    it("#when called with padded string #then trims before returning object format", () => {
      expect(mapClaudeModelToOpenCode("  claude-sonnet-4-6  ")).toEqual({ providerID: "anthropic", modelID: "claude-sonnet-4-6" })
    })
  })

  describe("#given anthropicProvider override", () => {
    it("#when called with opus and custom provider #then maps to custom provider", () => {
      expect(mapClaudeModelToOpenCode("opus", "kiro")).toEqual({ providerID: "kiro", modelID: "claude-opus-4-7" })
    })

    it("#when called with sonnet and custom provider #then maps to custom provider", () => {
      expect(mapClaudeModelToOpenCode("sonnet", "kiro")).toEqual({ providerID: "kiro", modelID: "claude-sonnet-4-6" })
    })

    it("#when called with haiku and custom provider #then maps to custom provider", () => {
      expect(mapClaudeModelToOpenCode("haiku", "my-gateway")).toEqual({ providerID: "my-gateway", modelID: "claude-haiku-4-5" })
    })

    it("#when called with bare claude model and custom provider #then uses custom provider", () => {
      expect(mapClaudeModelToOpenCode("claude-opus-4-6", "kiro")).toEqual({ providerID: "kiro", modelID: "claude-opus-4-6" })
    })

    it("#when called with explicit provider/model format #then preserves original provider", () => {
      expect(mapClaudeModelToOpenCode("openai/gpt-5.5", "kiro")).toEqual({ providerID: "openai", modelID: "gpt-5.5" })
    })

    it("#when called without anthropicProvider #then defaults to anthropic", () => {
      expect(mapClaudeModelToOpenCode("opus")).toEqual({ providerID: "anthropic", modelID: "claude-opus-4-7" })
    })
  })
})

import { normalizeModelFormat } from "../../shared/model-format-normalizer"
import { normalizeModelID } from "../../shared/model-normalization"

const ANTHROPIC_PREFIX = "anthropic/"

const CLAUDE_CODE_ALIAS_MAP = new Map<string, string>([
  ["sonnet", `${ANTHROPIC_PREFIX}claude-sonnet-4-6`],
  ["opus", `${ANTHROPIC_PREFIX}claude-opus-4-7`],
  ["haiku", `${ANTHROPIC_PREFIX}claude-haiku-4-5`],
])

function mapClaudeModelString(model: string | undefined, anthropicProvider?: string): string | undefined {
  if (!model) return undefined
  if (typeof model !== "string") return undefined

  const trimmed = model.trim()
  if (trimmed.length === 0) return undefined

  if (trimmed === "inherit") return undefined

  const prefix = anthropicProvider ? `${anthropicProvider}/` : ANTHROPIC_PREFIX
  const aliasResult = CLAUDE_CODE_ALIAS_MAP.get(trimmed.toLowerCase())
  if (aliasResult) return anthropicProvider ? aliasResult.replace(ANTHROPIC_PREFIX, prefix) : aliasResult

  if (trimmed.includes("/")) {
    const [providerID, ...modelParts] = trimmed.split("/")
    const modelID = modelParts.join("/")

    if (providerID.length === 0 || modelID.length === 0) return trimmed

    return modelID.startsWith("claude-")
      ? `${providerID}/${normalizeModelID(modelID)}`
      : trimmed
  }

  const normalized = normalizeModelID(trimmed)

  if (normalized.startsWith("claude-")) {
    return `${prefix}${normalized}`
  }

  return undefined
}

export function mapClaudeModelToOpenCode(
  model: string | undefined,
  anthropicProvider?: string,
): { providerID: string; modelID: string } | undefined {
  const mappedModel = mapClaudeModelString(model, anthropicProvider)
  return mappedModel ? normalizeModelFormat(mappedModel) : undefined
}

import { describe, test, expect, afterEach } from "bun:test"
import { mkdtempSync, writeFileSync, rmSync } from "fs"
import { join } from "path"
import { tmpdir } from "os"
import { parseJsonAgentFile } from "./json-agent-loader"

describe("json-agent-loader", () => {
  const dirs: string[] = []

  afterEach(() => {
    for (const dir of dirs) {
      rmSync(dir, { recursive: true, force: true })
    }
    dirs.length = 0
  })

  function trackDir(dir: string): string {
    dirs.push(dir)
    return dir
  }

  test("parses valid JSON agent file", () => {
    const dir = trackDir(mkdtempSync(join(tmpdir(), "json-agent-loader-test-")))
    const filePath = join(dir, "agent.json")

    writeFileSync(filePath, JSON.stringify({
      name: "test-agent",
      description: "A test agent",
      prompt: "You are a test agent.",
      tools: ["Bash", "Read"],
      model: "claude-3-5-sonnet-20241022",
      mode: "subagent",
    }), "utf-8")

    const result = parseJsonAgentFile(filePath, "definition-file")

    expect(result).not.toBeNull()
    expect(result?.name).toBe("test-agent")
    expect(result?.path).toBe(filePath)
    expect(result?.scope).toBe("definition-file")
    expect(result?.config.description).toBe("(definition-file) A test agent")
    expect(result?.config.prompt).toBe("You are a test agent.")
    expect(result?.config.mode).toBe("subagent")
    expect(result?.config.tools).toEqual({ bash: true, read: true })
  })

  test("parses JSONC with comments", () => {
    const dir = trackDir(mkdtempSync(join(tmpdir(), "json-agent-loader-test-")))
    const filePath = join(dir, "agent.jsonc")

    writeFileSync(filePath, `{
  // Agent name
  "name": "commented-agent",
  "description": "Agent with comments",
  "prompt": "Do something.",
  "tools": ["Bash"], // Tools for the agent
  // Model specification
  "model": "claude-3-5-sonnet-20241022"
}`, "utf-8")

    const result = parseJsonAgentFile(filePath, "definition-file")

    expect(result).not.toBeNull()
    expect(result?.name).toBe("commented-agent")
    expect(result?.config.tools).toEqual({ bash: true })
  })

  test("returns null when required fields are missing (name)", () => {
    const dir = trackDir(mkdtempSync(join(tmpdir(), "json-agent-loader-test-")))
    const filePath = join(dir, "agent.json")

    writeFileSync(filePath, JSON.stringify({
      description: "Missing name",
      prompt: "You are an agent.",
    }), "utf-8")

    const result = parseJsonAgentFile(filePath, "definition-file")
    expect(result).toBeNull()
