  it("#given command directory access throws a non-Error value #when loading project commands #then it returns the empty fallback", async () => {
    // given
    const accessSpy = spyOn(fs, "access").mockImplementation(() => {
      throw "access failed"
    })

    try {
      // when
      const commands = await loader.loadProjectCommands(TEST_DIR)

      // then
      expect(commands).toEqual({})
    } finally {
      accessSpy.mockRestore()
    }
  })
})

import { promises as fs, type Dirent } from "fs"
import { join, basename } from "path"
import { parseFrontmatter } from "../../shared/frontmatter"
import { sanitizeModelField } from "../../shared/model-sanitizer"
import { isMarkdownFile } from "../../shared/file-utils"
import {
  EXCLUDED_DIRS,
  findProjectOpencodeCommandDirs,
  getClaudeConfigDir,
  getOpenCodeCommandDirs,
} from "../../shared"
import { log } from "../../shared/logger"
import {
  clearCommandLoaderCache,
  deleteCachedCommands,
  getCachedCommands,
  getCommandLoaderCacheKey,
  setCachedCommands,
} from "./loader-cache"
import type { CommandScope, CommandDefinition, CommandFrontmatter, LoadedCommand } from "./types"

export { clearCommandLoaderCache }

async function loadCommandsFromDir(
  commandsDir: string,
  scope: CommandScope,
  visited: Set<string> = new Set(),
  prefix: string = ""
): Promise<LoadedCommand[]> {
  try {
    await fs.access(commandsDir)
  } catch (error) {
    if (error instanceof Error) {
      return []
    }
    return []
  }

  let realPath: string
  try {
    realPath = await fs.realpath(commandsDir)
  } catch (error) {
    if (error instanceof Error) {
      log(`Failed to resolve command directory: ${commandsDir}`, error)
    } else {
      log(`Failed to resolve command directory: ${commandsDir}`, error)
    }
    return []
  }

  if (visited.has(realPath)) {
    return []
  }
  visited.add(realPath)

  let entries: Dirent[]
  try {
    entries = await fs.readdir(commandsDir, { withFileTypes: true })
  } catch (error) {
    if (error instanceof Error) {
      log(`Failed to read command directory: ${commandsDir}`, error)
    } else {
      log(`Failed to read command directory: ${commandsDir}`, error)
    }
    return []
  }

  const commands: LoadedCommand[] = []

  for (const entry of entries) {
    if (entry.isDirectory()) {
      if (EXCLUDED_DIRS.has(entry.name)) continue
      if (entry.name.startsWith(".")) continue
      const subDirPath = join(commandsDir, entry.name)
      const subPrefix = prefix ? `${prefix}/${entry.name}` : entry.name
      const subCommands = await loadCommandsFromDir(subDirPath, scope, visited, subPrefix)
      commands.push(...subCommands)
      continue
    }

    if (!isMarkdownFile(entry)) continue

    const commandPath = join(commandsDir, entry.name)
    const baseCommandName = basename(entry.name, ".md")
    const commandName = prefix ? `${prefix}/${baseCommandName}` : baseCommandName

    try {
      const content = await fs.readFile(commandPath, "utf-8")
      const { data, body } = parseFrontmatter<CommandFrontmatter>(content)

      const wrappedTemplate = `<command-instruction>
${body.trim()}
</command-instruction>

<user-request>
$ARGUMENTS
</user-request>`

      const formattedDescription = `(${scope}) ${data.description || ""}`

      const isOpencodeSource = scope === "opencode" || scope === "opencode-project"
      const definition: CommandDefinition = {
        name: commandName,
        description: formattedDescription,
        template: wrappedTemplate,
        agent: data.agent,
        model: sanitizeModelField(data.model, isOpencodeSource ? "opencode" : "claude-code"),
        subtask: data.subtask,
        argumentHint: data["argument-hint"],
        handoffs: data.handoffs,
      }

      commands.push({
        name: commandName,
        path: commandPath,
        definition,
        scope,
      })
    } catch (error) {
      if (error instanceof Error) {
        log(`Failed to parse command: ${commandPath}`, error)
      } else {
        log(`Failed to parse command: ${commandPath}`, error)
      }
      continue
    }
  }

  return commands
}

function deduplicateLoadedCommandsByName(commands: LoadedCommand[]): LoadedCommand[] {
  const seen = new Set<string>()
  const deduplicatedCommands: LoadedCommand[] = []

  for (const command of commands) {
    if (seen.has(command.name)) {
      continue
    }

    seen.add(command.name)
    deduplicatedCommands.push(command)
  }

  return deduplicatedCommands
}

function commandsToRecord(commands: LoadedCommand[]): Record<string, CommandDefinition> {
  const result: Record<string, CommandDefinition> = {}
  for (const cmd of deduplicateLoadedCommandsByName(commands)) {
    const { name: _name, argumentHint: _argumentHint, ...openCodeCompatible } = cmd.definition
    result[cmd.name] = openCodeCompatible as CommandDefinition
  }
  return result
}

export async function loadUserCommands(): Promise<Record<string, CommandDefinition>> {
  const userCommandsDir = join(getClaudeConfigDir(), "commands")
  const commands = await loadCommandsFromDir(userCommandsDir, "user")
  return commandsToRecord(commands)
}

export async function loadProjectCommands(directory?: string): Promise<Record<string, CommandDefinition>> {
  const projectCommandsDir = join(directory ?? process.cwd(), ".claude", "commands")
  const commands = await loadCommandsFromDir(projectCommandsDir, "project")
  return commandsToRecord(commands)
}

export async function loadOpencodeGlobalCommands(): Promise<Record<string, CommandDefinition>> {
  const opencodeCommandDirs = getOpenCodeCommandDirs({ binary: "opencode" })
  const allCommands = await Promise.all(
    opencodeCommandDirs.map((commandsDir) => loadCommandsFromDir(commandsDir, "opencode")),
  )
  return commandsToRecord(allCommands.flat())
}

export async function loadOpencodeProjectCommands(directory?: string): Promise<Record<string, CommandDefinition>> {
  const opencodeProjectDirs = findProjectOpencodeCommandDirs(directory ?? process.cwd())
  const allCommands = await Promise.all(
    opencodeProjectDirs.map((commandsDir) =>
      loadCommandsFromDir(commandsDir, "opencode-project"),
    ),
  )
  return commandsToRecord(allCommands.flat())
}

export async function loadAllCommands(directory?: string): Promise<Record<string, CommandDefinition>> {
  const cacheKey = await getCommandLoaderCacheKey(directory)
  const cachedCommands = getCachedCommands(cacheKey)
  if (cachedCommands) {
    return cachedCommands
  }

  const loadCommandsPromise = Promise.all([
    loadUserCommands(),
    loadProjectCommands(directory),
    loadOpencodeGlobalCommands(),
    loadOpencodeProjectCommands(directory),
  ])
    .then(([user, project, global, projectOpencode]) => {
      return { ...projectOpencode, ...global, ...project, ...user }
    })
    .catch((error) => {
      deleteCachedCommands(cacheKey)
      if (error instanceof Error) {
        throw error
      }
      throw error
    })

  setCachedCommands(cacheKey, loadCommandsPromise)
  return loadCommandsPromise
}

export type CommandScope = "user" | "project" | "opencode" | "opencode-project"

/**
 * Handoff definition for command workflows.
 * Based on speckit's handoff pattern for multi-agent orchestration.
 * @see https://github.com/github/spec-kit
 */
export interface HandoffDefinition {
  /** Human-readable label for the handoff action */
  label: string
  /** Target agent/command identifier (e.g., "speckit.tasks") */
  agent: string
  /** Pre-filled prompt text for the handoff */
  prompt: string
  /** If true, automatically executes after command completion; if false, shows as suggestion */
  send?: boolean
}

export interface CommandDefinition {
  name: string
  description?: string
  template: string
  agent?: string
  model?: string
  subtask?: boolean
  argumentHint?: string
  /** Handoff definitions for workflow transitions */
  handoffs?: HandoffDefinition[]
}

export interface CommandFrontmatter {
  description?: string
  "argument-hint"?: string
  agent?: string
  model?: string
  subtask?: boolean
  /** Handoff definitions for workflow transitions */
  handoffs?: HandoffDefinition[]
}

export interface LoadedCommand {
  name: string
  path: string
  definition: CommandDefinition
  scope: CommandScope
}

const BUILTIN_ALLOWED_MCP_ENV_VARS = [
  "PATH",
  "HOME",
  "USER",
  "SHELL",
  "TERM",
  "TMPDIR",
  "TMP",
  "TEMP",
  "PWD",
  "OLDPWD",
  "LANG",
  "LC_ALL",
  "LC_CTYPE",
  "EDITOR",
  "VISUAL",
  "XDG_CONFIG_HOME",
  "XDG_DATA_HOME",
  "XDG_CACHE_HOME",
  "HOSTNAME",
  "LOGNAME",
  "USERPROFILE",
  "APPDATA",
  "LOCALAPPDATA",
]
const SENSITIVE_MCP_ENV_VAR_PATTERN = /KEY|TOKEN|SECRET|PASSWORD|AUTH|CREDENTIAL/i

let additionalAllowedMcpEnvVars = new Set<string>()

export function getAllowedMcpEnvVars(): Set<string> {
  return new Set([...BUILTIN_ALLOWED_MCP_ENV_VARS, ...additionalAllowedMcpEnvVars])
}

export function isSensitiveMcpEnvVar(varName: string): boolean {
  return SENSITIVE_MCP_ENV_VAR_PATTERN.test(varName)
}

export function isAllowedMcpEnvVar(varName: string): boolean {
  return getAllowedMcpEnvVars().has(varName)
}

export function setAdditionalAllowedMcpEnvVars(varNames: string[]): void {
  additionalAllowedMcpEnvVars = new Set(varNames)
}

export function resetAdditionalAllowedMcpEnvVars(): void {
  additionalAllowedMcpEnvVars = new Set()
}

