import { afterEach, beforeEach, describe, expect, test } from "bun:test"
import { mkdtempSync, rmSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { loadPluginHooksConfigs } from "./hook-loader"
import type { LoadedPlugin } from "./types"

// Regression coverage for #4458 - every command/http action loaded from a
// plugin's hooks config must carry the plugin's installPath as `pluginRoot`
// so the downstream dispatcher can export CLAUDE_PLUGIN_ROOT on the spawn.
describe("loadPluginHooksConfigs pluginRoot stamping (#4458)", () => {
  let tempDirectory = ""

  beforeEach(() => {
    tempDirectory = mkdtempSync(join(tmpdir(), "omo-hook-loader-"))
  })

  afterEach(() => {
    rmSync(tempDirectory, { recursive: true, force: true })
  })

  function makePlugin(pluginName: string, hooksJson: unknown): LoadedPlugin {
    const installPath = join(tempDirectory, pluginName)
    const hooksPath = join(installPath, "hooks.json")
    // Use mkdir via writeFileSync target dir trick - easier to just create the
    // install dir explicitly.
    rmSync(installPath, { recursive: true, force: true })
    const fs = require("node:fs") as typeof import("node:fs")
    fs.mkdirSync(installPath, { recursive: true })
    writeFileSync(hooksPath, JSON.stringify(hooksJson), "utf-8")
    return {
      name: pluginName,
      version: "0.0.0",
      scope: "user",
      installPath,
      pluginKey: `${pluginName}@test`,
      hooksPath,
    }
  }

  test("#given a plugin hooks config #when loaded #then every command action carries pluginRoot=installPath", () => {
    // given
    const plugin = makePlugin("hello-plugin", {
      hooks: {
        UserPromptSubmit: [
          {
            matcher: "*",
            hooks: [
              { type: "command", command: "echo hi" },
              { type: "command", command: "${CLAUDE_PLUGIN_ROOT}/scripts/foo.sh" },
            ],
          },
        ],
      },
    })

    // when
    const configs = loadPluginHooksConfigs([plugin])

    // then
    expect(configs).toHaveLength(1)
    const matchers = configs[0]?.hooks?.UserPromptSubmit ?? []
    expect(matchers).toHaveLength(1)
    const actions = matchers[0]?.hooks ?? []
    expect(actions).toHaveLength(2)
    for (const action of actions) {
      expect(action.type).toBe("command")
      // Type narrowing for the test: command-type entries should carry pluginRoot.
      expect((action as { pluginRoot?: string }).pluginRoot).toBe(plugin.installPath)
    }
  })

  test("#given an http action #when loaded #then it also carries pluginRoot", () => {
    // given
    const plugin = makePlugin("http-plugin", {
      hooks: {
        PostToolUse: [
          {
            matcher: "Bash",
            hooks: [
              { type: "http", url: "https://example.test/hook" },
            ],
          },
        ],
      },
    })

    // when
    const configs = loadPluginHooksConfigs([plugin])

    // then
    const action = configs[0]?.hooks?.PostToolUse?.[0]?.hooks?.[0]
    expect(action?.type).toBe("http")
    expect((action as { pluginRoot?: string }).pluginRoot).toBe(plugin.installPath)
  })
})

import { existsSync, readFileSync } from "fs"
import { log } from "../../shared/logger"
import type { HookEntry, HooksConfig, LoadedPlugin } from "./types"
import { resolvePluginPaths } from "./plugin-path-resolver"

/**
 * Stamp every action with the plugin's installPath so that the downstream
 * dispatcher can set CLAUDE_PLUGIN_ROOT on the spawned hook process (#4458).
 * The plugin association is otherwise lost once configs are merged together.
 */
function stampPluginRoot(config: HooksConfig, pluginRoot: string): void {
  const eventMap = config.hooks
  if (!eventMap) return
  for (const matchers of Object.values(eventMap)) {
    if (!Array.isArray(matchers)) continue
    for (const matcher of matchers) {
      if (!Array.isArray(matcher?.hooks)) continue
      for (const action of matcher.hooks as HookEntry[]) {
        if (action && (action.type === "command" || action.type === "http")) {
          action.pluginRoot = pluginRoot
        }
      }
    }
  }
}

export function loadPluginHooksConfigs(plugins: LoadedPlugin[]): HooksConfig[] {
  const configs: HooksConfig[] = []

  for (const plugin of plugins) {
    if (!plugin.hooksPath || !existsSync(plugin.hooksPath)) continue

    try {
      const content = readFileSync(plugin.hooksPath, "utf-8")
      let config = JSON.parse(content) as HooksConfig

      config = resolvePluginPaths(config, plugin.installPath)
      stampPluginRoot(config, plugin.installPath)

      configs.push(config)
      log(`Loaded plugin hooks config from ${plugin.name}`, { path: plugin.hooksPath })
    } catch (error) {
      log(`Failed to load plugin hooks config: ${plugin.hooksPath}`, error)
    }
  }

  return configs
}

import { existsSync, readdirSync } from "fs"
import { dirname, join } from "path"
import { log } from "../../shared/logger"
import { derivePluginNameFromKey } from "./plugin-key"
import { findPluginManifestPath, readManifestFromPath } from "./plugin-manifest"

function parseSemverPrefix(name: string): [number, number, number] | null {
  const match = name.match(/^(\d+)\.(\d+)\.(\d+)/)
  if (!match) return null
  return [parseInt(match[1], 10), parseInt(match[2], 10), parseInt(match[3], 10)]
}

const SEMVER_SUFFIX_MARKER = /^\d+\.\d+\.\d+[-+]/

function compareCandidatePriority(
  a: { name: string },
  b: { name: string },
): number {
  const aIsUnknown = a.name === "unknown"
  const bIsUnknown = b.name === "unknown"
  if (aIsUnknown && !bIsUnknown) return 1
  if (!aIsUnknown && bIsUnknown) return -1

  const aVer = parseSemverPrefix(a.name)
  const bVer = parseSemverPrefix(b.name)
  if (aVer && bVer) {
    if (aVer[0] !== bVer[0]) return bVer[0] - aVer[0]
    if (aVer[1] !== bVer[1]) return bVer[1] - aVer[1]
    if (aVer[2] !== bVer[2]) return bVer[2] - aVer[2]
    const aHasSuffix = SEMVER_SUFFIX_MARKER.test(a.name)
    const bHasSuffix = SEMVER_SUFFIX_MARKER.test(b.name)
    if (!aHasSuffix && bHasSuffix) return -1
    if (aHasSuffix && !bHasSuffix) return 1
    return a.name.localeCompare(b.name)
  }
  if (aVer && !bVer) return -1
  if (!aVer && bVer) return 1
  return a.name.localeCompare(b.name)
}

export function resolveActualInstallPath(
  configuredInstallPath: string,
  pluginKey?: string,
): string | null {
  if (existsSync(configuredInstallPath)) {
    return configuredInstallPath
  }
  const parentDir = dirname(configuredInstallPath)
  if (!existsSync(parentDir)) {
    return null
  }
  let entries: string[]
  try {
    entries = readdirSync(parentDir)
  } catch (error) {
    if (error instanceof Error) {
      log("Failed to scan plugin parent directory for fallback version", {
        parentDir,
        error,
      })
      return null
    }
    throw error
  }

  const expectedName = pluginKey ? derivePluginNameFromKey(pluginKey) : null

  const candidates = entries
    .map((name) => ({ name, path: join(parentDir, name) }))
    .filter(({ path }) => {
      const manifestPath = findPluginManifestPath(path)
      if (!manifestPath) return false
      if (expectedName === null) return true
      const manifest = readManifestFromPath(manifestPath)
      if (!manifest?.name) return false
      return manifest.name === expectedName
    })
    .sort(compareCandidatePriority)
  return candidates[0]?.path ?? null
}

import { existsSync, readFileSync } from "fs"
import { log } from "../../shared/logger"
import { getInstalledPluginsPath } from "./discovery-paths"
import type {
  InstalledPluginEntryV3,
  InstalledPluginsDatabase,
  PluginInstallation,
} from "./types"

export function loadInstalledPlugins(pluginsBaseDir?: string): InstalledPluginsDatabase | null {
  const dbPath = getInstalledPluginsPath(pluginsBaseDir)
  if (!existsSync(dbPath)) {
    return null
  }

  try {
    const content = readFileSync(dbPath, "utf-8")
    return JSON.parse(content) as InstalledPluginsDatabase
  } catch (error) {
    if (error instanceof Error) {
      log("Failed to load installed plugins database", error)
      return null
    }
    throw error
  }
}

function v3EntryToInstallation(entry: InstalledPluginEntryV3): PluginInstallation {
  return {
    scope: entry.scope,
    installPath: entry.installPath,
    version: entry.version,
    installedAt: entry.lastUpdated,
    lastUpdated: entry.lastUpdated,
    gitCommitSha: entry.gitCommitSha,
    projectPath: entry.projectPath,
  }
}

function isValidV3Entry(entry: unknown): entry is InstalledPluginEntryV3 {
  return (
    entry != null &&
    typeof entry === "object" &&
    typeof (entry as Record<string, unknown>).name === "string" &&
    typeof (entry as Record<string, unknown>).marketplace === "string" &&
    typeof (entry as Record<string, unknown>).installPath === "string"
  )
}

export function extractPluginEntries(
  db: InstalledPluginsDatabase,
): Array<[string, PluginInstallation | undefined]> {
  if (Array.isArray(db)) {
    return db
      .filter(isValidV3Entry)
      .map((entry) => [
        `${entry.name}@${entry.marketplace}`,
        v3EntryToInstallation(entry),
      ])
  }
  if (db.version === 1) {
    return Object.entries(db.plugins).map(([key, installation]) => [key, installation])
  }
  return Object.entries(db.plugins).map(([key, installations]) => [key, installations[0]])
}

import { existsSync } from "fs"
import { join } from "path"
import { derivePluginNameFromKey } from "./plugin-key"
import type {
  LoadedPlugin,
  PluginInstallation,
  PluginManifest,
} from "./types"

function resolveVersion(
  installationVersionValue: string,
  manifestVersionValue: string | undefined,
): string {
  const installationVersionTrim = installationVersionValue.trim()
  const installationVersion =
    installationVersionTrim !== "" && installationVersionTrim !== "unknown"
      ? installationVersionValue
      : null
  const manifestVersionTrim =
    typeof manifestVersionValue === "string" ? manifestVersionValue.trim() : ""
  const manifestVersion = manifestVersionTrim !== "" ? manifestVersionValue : null
  const rawVersion = installationVersionTrim !== "" ? installationVersionValue : null
  return installationVersion ?? manifestVersion ?? rawVersion ?? "unknown"
}

export function createLoadedPlugin(
  pluginKey: string,
  installation: PluginInstallation,
  installPath: string,
  manifest: PluginManifest | null,
): LoadedPlugin {
  const loadedPlugin: LoadedPlugin = {
    name: manifest?.name || derivePluginNameFromKey(pluginKey),
    version: resolveVersion(installation.version, manifest?.version),
    scope: installation.scope,
    installPath,
    pluginKey,
    manifest: manifest ?? undefined,
  }

  if (existsSync(join(installPath, "commands"))) {
    loadedPlugin.commandsDir = join(installPath, "commands")
  }
  if (existsSync(join(installPath, "agents"))) {
    loadedPlugin.agentsDir = join(installPath, "agents")
  }
  if (existsSync(join(installPath, "skills"))) {
    loadedPlugin.skillsDir = join(installPath, "skills")
  }

  const hooksPath = join(installPath, "hooks", "hooks.json")
  if (existsSync(hooksPath)) {
    loadedPlugin.hooksPath = hooksPath
  }

  const mcpPath = join(installPath, ".mcp.json")
  if (existsSync(mcpPath)) {
    loadedPlugin.mcpPath = mcpPath
  }

  return loadedPlugin
}

