}

import { existsSync, realpathSync } from "node:fs"
import { homedir } from "node:os"
import { join, posix, resolve, win32 } from "node:path"

import { CONFIG_BASENAME } from "./plugin-identity"

import type {
  OpenCodeBinaryType,
  OpenCodeConfigDirOptions,
  OpenCodeConfigPaths,
} from "./opencode-config-dir-types"

export type {
  OpenCodeBinaryType,
  OpenCodeConfigDirOptions,
  OpenCodeConfigPaths,
} from "./opencode-config-dir-types"

export const TAURI_APP_IDENTIFIER = "ai.opencode.desktop"
export const TAURI_APP_IDENTIFIER_DEV = "ai.opencode.desktop.dev"

export function isDevBuild(version: string | null | undefined): boolean {
  if (!version) return false
  return version.includes("-dev") || version.includes(".dev")
}

function getTauriConfigDir(identifier: string): string {
  const platform = process.platform

  switch (platform) {
    case "darwin":
      return join(homedir(), "Library", "Application Support", identifier)

    case "win32": {
      const appData = process.env.APPDATA || join(homedir(), "AppData", "Roaming")
      return win32.join(appData, identifier)
    }

    case "linux":
    default: {
      const xdgConfig = process.env.XDG_CONFIG_HOME || join(homedir(), ".config")
      return join(xdgConfig, identifier)
    }
  }
}

function resolveConfigPath(pathValue: string): string {
  if (isWslEnvironment() && pathValue.startsWith("/")) {
    return posix.normalize(pathValue)
  }

  const resolvedPath = resolve(pathValue)
  if (!existsSync(resolvedPath)) return resolvedPath

  try {
    return realpathSync(resolvedPath)
  } catch (error) {
    if (error instanceof Error) {
      return resolvedPath
    }
    return resolvedPath
  }
}

function isWslEnvironment(): boolean {
  return process.platform === "linux" &&
    (Boolean(process.env.WSL_DISTRO_NAME?.trim()) || Boolean(process.env.WSL_INTEROP?.trim()))
}

function isWindowsUserConfigRoot(pathValue: string): boolean {
  const normalizedPath = pathValue.replaceAll("\\", "/").toLowerCase()
  return /^[a-z]:\/users\//.test(normalizedPath) || /^\/mnt\/[a-z]\/users\//.test(normalizedPath)
}

function getWindowsUserFromConfigRoot(pathValue: string): string | null {
  const normalizedPath = pathValue.replaceAll("\\", "/")
  const match = /^(?:[a-z]:|\/mnt\/[a-z])\/Users\/([^/]+)/i.exec(normalizedPath)
  return match?.[1] ?? null
}

function getWslLinuxHomeDir(windowsConfigRoot?: string): string | null {
  const envHome = process.env.HOME?.trim()
  if (envHome && envHome.startsWith("/") && !isWindowsUserConfigRoot(envHome)) {
    return envHome
  }

  const user = process.env.USER?.trim() || process.env.LOGNAME?.trim() ||
    process.env.SUDO_USER?.trim() ||
    (windowsConfigRoot ? getWindowsUserFromConfigRoot(windowsConfigRoot) : undefined)
  return user ? posix.join("/home", user) : null
}

function getCliDefaultConfigDir(): string {
  const envXdgConfig = process.env.XDG_CONFIG_HOME?.trim()
  const shouldIgnoreWindowsXdg = envXdgConfig !== undefined && envXdgConfig.length > 0 &&
    isWslEnvironment() && isWindowsUserConfigRoot(envXdgConfig)
  const xdgConfig = shouldIgnoreWindowsXdg
    ? posix.join(getWslLinuxHomeDir(envXdgConfig) ?? "/home", ".config")
    : envXdgConfig || join(homedir(), ".config")
  const configDir = isWslEnvironment() ? posix.join(xdgConfig, "opencode") : join(xdgConfig, "opencode")
  return resolveConfigPath(configDir)
}

function getCliCustomConfigDir(): string | null {
  const envConfigDir = process.env.OPENCODE_CONFIG_DIR?.trim()
  if (!envConfigDir) {
    return null
  }

  return resolveConfigPath(envConfigDir)
}

function getCliConfigDir(): string {
  return getCliCustomConfigDir() ?? getCliDefaultConfigDir()
}

export function getOpenCodeConfigDirs(options: OpenCodeConfigDirOptions): string[] {
  if (options.binary !== "opencode") {
    return [getOpenCodeConfigDir(options)]
  }

  const customConfigDir = getCliCustomConfigDir()

  return Array.from(
    new Set([
      ...(customConfigDir ? [customConfigDir] : []),
      getCliDefaultConfigDir(),
    ]),
  )
}

export function getOpenCodeConfigDir(options: OpenCodeConfigDirOptions): string {
  const { binary, version, checkExisting = true } = options

  if (binary === "opencode") {
    return getCliConfigDir()
  }

  const identifier = isDevBuild(version) ? TAURI_APP_IDENTIFIER_DEV : TAURI_APP_IDENTIFIER
  const tauriDirBase = getTauriConfigDir(identifier)
  const tauriDir = process.platform === "win32"
    ? (win32.isAbsolute(tauriDirBase) ? win32.normalize(tauriDirBase) : win32.resolve(tauriDirBase))
    : resolveConfigPath(tauriDirBase)

  if (checkExisting) {
    const legacyDir = getCliConfigDir()
    const legacyConfig = join(legacyDir, "opencode.json")
    const legacyConfigC = join(legacyDir, "opencode.jsonc")

    if (existsSync(legacyConfig) || existsSync(legacyConfigC)) {
      return legacyDir
    }
  }

  return tauriDir
}

export function getOpenCodeConfigPaths(options: OpenCodeConfigDirOptions): OpenCodeConfigPaths {
  const configDir = getOpenCodeConfigDir(options)

  return {
    configDir,
    configJson: join(configDir, "opencode.json"),
    configJsonc: join(configDir, "opencode.jsonc"),
    packageJson: join(configDir, "package.json"),
    omoConfig: join(configDir, `${CONFIG_BASENAME}.json`),
  }
}

export function detectExistingConfigDir(binary: OpenCodeBinaryType, version?: string | null): string | null {
  const locations: string[] = []

  const envConfigDir = process.env.OPENCODE_CONFIG_DIR?.trim()
  if (envConfigDir) {
    locations.push(resolveConfigPath(envConfigDir))
  }

  if (binary === "opencode-desktop") {
    const identifier = isDevBuild(version) ? TAURI_APP_IDENTIFIER_DEV : TAURI_APP_IDENTIFIER
    locations.push(getTauriConfigDir(identifier))

    if (isDevBuild(version)) {
      locations.push(getTauriConfigDir(TAURI_APP_IDENTIFIER))
    }
  }

  locations.push(getCliConfigDir())

  for (const dir of locations) {
    const configJson = join(dir, "opencode.json")
    const configJsonc = join(dir, "opencode.jsonc")

    if (existsSync(configJson) || existsSync(configJsonc)) {
      return dir
    }
  }

  return null
}

/**
 * Parses a tools configuration value into a boolean record.
 * Accepts comma-separated strings, string arrays, or unknown values from config files.
 * Returns undefined when input is empty or invalid.
 */
export function parseToolsConfig(toolsValue: unknown): Record<string, boolean> | undefined {
  if (!toolsValue) return undefined

  let items: string[]
  if (typeof toolsValue === "string") {
    items = toolsValue.split(",").map((t) => t.trim()).filter(Boolean)
  } else if (Array.isArray(toolsValue)) {
    items = toolsValue.filter((t) => typeof t === "string" && t.trim().length > 0).map((t) => (t as string).trim())
  } else {
    return undefined
  }

  if (items.length === 0) return undefined

  const result: Record<string, boolean> = {}
  for (const tool of items) {
    result[tool.toLowerCase()] = true
  }
  return result
}

import { execFileSync } from "node:child_process"
import { existsSync, realpathSync } from "node:fs"
import { dirname, join, resolve, win32 } from "node:path"

const worktreePathCache = new Map<string, string | undefined>()

function normalizePath(path: string): string {
  const resolvedPath = process.platform !== "win32" && win32.isAbsolute(path) ? path : resolve(path)
  if (!existsSync(resolvedPath)) {
    return resolvedPath
  }

  try {
    return realpathSync.native(resolvedPath)
  } catch (error) {
    if (!(error instanceof Error)) {
      throw error
    }
    try {
      return realpathSync(resolvedPath)
    } catch (fallbackError) {
      if (!(fallbackError instanceof Error)) {
        throw fallbackError
      }
      return resolvedPath
    }
  }
}

function pathKey(path: string): string {
  const normalized = path.replace(/\\/g, "/")
  return process.platform === "win32" ? normalized.toLowerCase() : normalized
}

function detectWorktreePath(directory: string): string | undefined {
  const resolvedDirectory = resolve(directory)
  const cacheKey = pathKey(normalizePath(resolvedDirectory))
  if (worktreePathCache.has(cacheKey)) {
    return worktreePathCache.get(cacheKey)
  }

  const gitMarkerAncestor = findGitMarkerAncestor(resolvedDirectory)
  if (gitMarkerAncestor !== undefined) {
    worktreePathCache.set(cacheKey, gitMarkerAncestor)
    return gitMarkerAncestor
  }

  try {
    const worktreePath = execFileSync("git", ["rev-parse", "--show-toplevel"], {
      cwd: resolvedDirectory,
      encoding: "utf-8",
      timeout: 5000,
      stdio: ["pipe", "pipe", "pipe"],
    }).trim()
    const normalizedWorktreePath = normalizePath(worktreePath)

    worktreePathCache.set(cacheKey, normalizedWorktreePath)
    return normalizedWorktreePath
  } catch (error) {
    if (!(error instanceof Error)) {
      throw error
    }
    worktreePathCache.set(cacheKey, undefined)
    return undefined
  }
}

function findGitMarkerAncestor(directory: string): string | undefined {
  let currentDirectory = normalizePath(directory)

  while (true) {
    if (existsSync(join(currentDirectory, ".git"))) {
      return currentDirectory
    }

    const parentDirectory = dirname(currentDirectory)
    if (parentDirectory === currentDirectory) {
      return undefined
    }

    currentDirectory = normalizePath(parentDirectory)
  }
}

function findAncestorDirectories(
  startDirectory: string,
  targetPaths: ReadonlyArray<ReadonlyArray<string>>,
  stopDirectory?: string,
): string[] {
  const directories: string[] = []
  const seen = new Set<string>()
  let currentDirectory = normalizePath(startDirectory)
  const resolvedStopDirectory = stopDirectory ? normalizePath(stopDirectory) : undefined
  const stopDirectoryKey = resolvedStopDirectory ? pathKey(resolvedStopDirectory) : undefined

  while (true) {
    for (const targetPath of targetPaths) {
      const candidateDirectory = join(currentDirectory, ...targetPath)
      if (!existsSync(candidateDirectory)) {
        continue
      }

      const normalizedCandidateDirectory = normalizePath(candidateDirectory)
      const candidateDirectoryKey = pathKey(normalizedCandidateDirectory)
      if (seen.has(candidateDirectoryKey)) {
        continue
      }

      seen.add(candidateDirectoryKey)
      directories.push(normalizedCandidateDirectory)
    }

    if (stopDirectoryKey === pathKey(currentDirectory)) {
      return directories
    }

    const parentDirectory = dirname(currentDirectory)
    if (parentDirectory === currentDirectory) {
      return directories
    }

    currentDirectory = normalizePath(parentDirectory)
  }
}

export function findProjectOpencodeCommandDirs(startDirectory: string, stopDirectory?: string): string[] {
  const detectedStopDirectory = stopDirectory ?? detectWorktreePath(startDirectory) ?? findGitMarkerAncestor(startDirectory)

  return findAncestorDirectories(
    startDirectory,
    [
      [".opencode", "commands"],
      [".opencode", "command"],
    ],
    detectedStopDirectory,
  )
}

import { homedir } from "os"
import { isAbsolute, join, resolve } from "path"
import { isWithinProject } from "./contains-path"
import { log } from "./logger"

export function resolveAgentDefinitionPaths(
  paths: string[],
  baseDir: string,
  containmentDir: string | null
): string[] {
  return paths.flatMap((p) => {
    const expanded = p.startsWith("~/") ? join(homedir(), p.slice(2)) : p
    const resolved = isAbsolute(expanded) ? expanded : resolve(baseDir, expanded)

    if (containmentDir !== null && !isWithinProject(resolved, containmentDir)) {
      log(`agent_definitions path rejected (outside project boundary): ${p} -> ${resolved}`)
      return []
    }

    return [resolved]
  })
}
